select.where:
 and member_id = #{memberId}
 and activity_id = #{activityId}
 and topic_id = #{topicId}
 and node_id = #{nodeId}
 and play_instance_id = #{playInstanceId}

    and play_instance_id=coalesce((select r.play_instance_id from topic_route_session r where r.member_id=player_node_progress.member_id and r.topic_id=player_node_progress.topic_id and r.activity_id=player_node_progress.activity_id order by r.id desc limit 1),'default')

and del_flag = 0

mapper.update:
update player_node_progress
set status = 1
where member_id = #{memberId} and activity_id = #{activityId}
  and topic_id = #{topicId} and node_id = #{nodeId}
  and play_instance_id=coalesce((select r.play_instance_id from topic_route_session r where r.member_id=#{memberId} and r.topic_id=#{topicId} and r.activity_id=#{activityId} order by r.id desc limit 1),'default')
  and status = 0 and del_flag = 0
